def create_variants_and_map_order_items(apps, schema_editor):
    database = schema_editor.connection.alias
    Product = apps.get_model('shop', 'Product')
    ProductVariant = apps.get_model('shop', 'ProductVariant')
    OrderItem = apps.get_model('shop', 'OrderItem')

    for product in Product.objects.using(database).all().iterator():
        sizes = list(product.sizes.using(database).order_by('name').values_list('name', flat=True))
        colors = list(product.colors.using(database).order_by('name').values_list('name', flat=True))
        combinations = [
            (size, color)
            for size in (sizes or [''])
            for color in (colors or [''])
        ]
        stock = product.stock
        product.variant_inventory_enabled = bool(sizes or colors)
        product.save(update_fields=['variant_inventory_enabled'])

        variants = {}
        for index, (size, color) in enumerate(combinations):
            variant = ProductVariant.objects.using(database).create(
                product_id=product.pk,
                size=size,
                color=color,
                price=product.price,
                compare_at_price=product.compare_at_price,
                quantity=stock.quantity if index == 0 else 0,
                opening_quantity=stock.opening_quantity if index == 0 else 0,
                restocked_quantity=stock.restocked_quantity if index == 0 else 0,
            )
            variants[(size, color)] = variant

        for item in OrderItem.objects.using(database).filter(product_id=product.pk).iterator():
            option = (item.selected_size, item.selected_color)
            variant = variants.get(option)
            if variant is None:
                variant, _ = ProductVariant.objects.using(database).get_or_create(
                    product_id=product.pk,
                    size=item.selected_size,
                    color=item.selected_color,
                    defaults={
                        'price': item.unit_price,
                        'compare_at_price': None,
                    },
                )
            item.variant_id = variant.pk
            item.save(update_fields=['variant'])


